];

return [{json:{week, mode, messages:exampleMessages.filter(m => m.week === week)}}];

function countMessages(messages) {
  const alerts = new Map();
  const replies = new Map();
  let duplicates = 0;
  for (const message of messages) {
    if (message.event === "reply") {
      if (!replies.has(message.id)) replies.set(message.id, new Set());
      replies.get(message.id).add(message.text);
    } else if (message.event === "alert") {
      if (alerts.has(message.id)) duplicates++;
      else alerts.set(message.id, message);
    }
  }
  const items = [...alerts.values()].map(alert => ({
    id: alert.id, topic: alert.topic, text: alert.text,
    replies: [...(replies.get(alert.id) || [])]
  }));
  const waiting = items.filter(item => item.replies.length === 0);
  return {received: messages.length, unique: items.length, answered: items.length - waiting.length,
    duplicates, waiting: waiting.map(item => item.id), items};
}


const {week, mode, messages} = $input.first().json;
return [{json:{week,mode,metrics:countMessages(messages)}}];

// Extractive summarization: TextRank orders source sentences by weighted word overlap.
// Ties keep source order, so reruns of a small or disconnected example stay reproducible.
function selectEvidence(items) {
  const sentences = items.flatMap(item => [item.text, ...item.replies].map(text => ({id:item.id, text})));
  const stops = new Set("a an and are as at for from in its of on the to was were".split(" "));
  const tokens = sentences.map(s => new Set((s.text.toLowerCase().match(/[a-z]+/g) || []).filter(w => !stops.has(w))));
  const edges = tokens.map((left,i) => tokens.map((right,j) => {
    if (i === j || !left.size || !right.size) return 0;
    let shared = 0;
    for (const word of left) if (right.has(word)) shared++;
    return shared / Math.sqrt(left.size * right.size);
  }));
  const n = sentences.length;
  if (!n) return [];
  const totals = edges.map(row => row.reduce((a,b) => a+b,0));
  let scores = Array(n).fill(1/n);
  for (let pass = 0; pass < 24; pass++) {
    scores = sentences.map((_, i) => (1-.85)/n + .85*scores.reduce((sum, score, j) =>
      sum + score * (totals[j] ? edges[j][i]/totals[j] : 1/n), 0));
  }
  return sentences.map((s,i) => ({...s,score:scores[i]})).sort((a,b) => b.score-a.score)
    .slice(0,2).map(({id,text}) => ({id,text}));
}
