function makeReport(metrics, mode) {
  const lead = metrics.unique + " unique alerts. " + metrics.answered + " received a reply. " +
    (metrics.waiting.length ? "Follow up on " + metrics.waiting.join(", ") + "." : "All alerts received a reply.");
  const evidence = mode === "metrics" ? [] : selectEvidence(metrics.items);
  const result = {lead, evidence, metrics, method:mode === "metrics" ? "Metrics only" : "TextRank · extractive summary"};
  if (mode === "recorded") {
    const saved = recordedRuns.find(run => JSON.stringify(run.facts) === JSON.stringify(metrics));
    if (saved) return {...result, method:"Saved Qwen draft · verified against the same input", draft:saved.draft};
  }
  return result;
}

const {week, mode, metrics} = $input.first().json;
return [{json:{week,mode,...makeReport(metrics, mode)}}];

